# -*- coding: utf-8 -*-
"""
qc_unwrap_author_links.py — 清除 raw/ 剪藏文件里 Web Clipper 误加的作者名 wikilink。

背景（2026-09-29 关系图谱精简）：
  Obsidian Web Clipper 把论文 `author:` 字段的每个作者名都写成了
  `- "[[作者名]]"` 形式。这些 [[ ]] 在 Obsidian 眼里是链接，指向**不存在**的页面
  ⇒ 关系图谱里生成 ~977 个「点进去空白」的幽灵节点。
  作者名本就**不应**是 wikilink（库里没有、也不该有作者页面）。

本脚本做两件事（仅作用于 raw/**/*.md）：
  1. frontmatter 中 `author:` 下的 `- "[[X]]"` / `- [[X]]`  →  `- "X"`
     （保留引号，防 YAML 特殊字符；值从「链接」变成纯文本）
  2. 正文中 7 处 Web Clipper 图注残留：`![[Uncaptioned image]](URL)` → `![](URL)`
     以及 1 处数学记号 `∈[[1, n]]` → `∈[[1, n]`

安全纪律（对齐 CLAUDE.md「写盘脚本铁律」）：
  - 默认**干跑**，改盘须显式 `--apply`
  - `--apply` 前自动备份到库根 `.qc/ghost_backup_YYYYMMDD/`（见 kb_lib.qc_work_dir）
  - 写盘后用 **kb_lib.split_frontmatter 同一解析器**复核 fm 仍可解析
  - 写后复算：处理 N 文件须复核 N 文件；并复跑未解析链接计数应为 0
  - 保留每个文件原有的换行风格（CRLF/LF 混合，勿统一）

用法：
  python tools/qc_unwrap_author_links.py            # 干跑，打印将改内容
  python tools/qc_unwrap_author_links.py --apply
  python tools/qc_unwrap_author_links.py --selftest
"""
import os
import re
import sys
import shutil
import datetime

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from kb_lib import split_frontmatter, qc_work_dir  # 必须用与被校验系统同一个解析器

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TARGET_DIR = "raw"

# --- frontmatter: `- "[[X]]"` / `- '[[X]]'` / `- [[X]]`  →  `- "X"`
FM_WRAP = re.compile(r'^(\s*-\s*)(["\']?)\[\[(.+?)\]\]\2[ \t]*$')
# --- body fixes
BODY_IMG = re.compile(r'!\[\[Uncaptioned image\]\]')
BODY_MATH = re.compile(r'\[\[1, n\]\]')

KEY = re.compile(r'^([A-Za-z_][A-Za-z0-9_-]*):')


def newline_style(raw):
    crlf = raw.count("\r\n")
    lf = raw.count("\n")
    if lf and crlf == lf:
        return "\r\n"
    return "\n"


def transform(text):
    """返回 (新文本, fm改动数, 正文改动数)。text 已归一化为 \\n。"""
    fm, body = split_frontmatter(text)

    fm_n = 0
    new_fm = fm
    if fm:
        out = []
        cur = None
        for line in fm.split("\n"):
            m = KEY.match(line)
            if m:
                cur = m.group(1)
                out.append(line)
                continue
            if cur == "author":
                mm = FM_WRAP.match(line)
                if mm:
                    indent, _q, val = mm.group(1), mm.group(2), mm.group(3)
                    # 值里若含双引号则转义，否则直接包双引号
                    val_esc = val.replace('"', '\\"')
                    out.append(f'{indent}"{val_esc}"')
                    fm_n += 1
                    continue
            out.append(line)
        new_fm = "\n".join(out)

    new_body, bn1 = BODY_IMG.subn("![]", body)
    new_body, bn2 = BODY_MATH.subn("[[1, n]", new_body)
    body_n = bn1 + bn2

    if fm_n == 0 and body_n == 0:
        return text, 0, 0
    if fm:
        return f"---\n{new_fm}\n---\n{new_body}", fm_n, body_n
    return new_body, fm_n, body_n


def iter_files():
    for dp, dn, fn in os.walk(os.path.join(ROOT, TARGET_DIR)):
        for f in sorted(fn):
            if f.endswith(".md"):
                yield os.path.join(dp, f)


def run(apply_it, verbose_limit=25):
    stamp = datetime.date.today().strftime("%Y%m%d")
    # 备份落到**库根 .qc**（create=True 会建目录，并阻断误写归档层）
    backup = os.path.join(qc_work_dir(create=True), f"ghost_backup_{stamp}")
    changed = []
    total_fm = total_body = 0
    for path in iter_files():
        raw = open(path, "rb").read().decode("utf-8")
        nl = newline_style(raw)
        norm = raw.replace("\r\n", "\n").replace("\r", "\n")
        had_fm = bool(split_frontmatter(norm)[0])
        new, f_n, b_n = transform(norm)
        if f_n == 0 and b_n == 0:
            continue
        # 复核 1：原本有 frontmatter 的文件，改写后必须仍能解析出来
        nfm, nbody = split_frontmatter(new)
        if had_fm and not nfm:
            print(f"  !! ABORT {path}: 改写后 frontmatter 解析失败")
            return 1
        if not had_fm and nfm:
            print(f"  !! ABORT {path}: 凭空产生了 frontmatter")
            return 1
        # 复核 2：frontmatter 里不得再残留 [[ ]]
        if nfm and "[[" in nfm:
            print(f"  !! ABORT {path}: frontmatter 仍有 [[ ]]")
            return 1
        out = new if nl == "\n" else new.replace("\n", nl)
        changed.append((path, f_n, b_n))
        total_fm += f_n
        total_body += b_n
        if apply_it:
            rel = os.path.relpath(path, ROOT)
            dst = os.path.join(backup, rel)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.copy2(path, dst)
            open(path, "wb").write(out.encode("utf-8"))

    print(f"{'APPLIED' if apply_it else 'DRY-RUN'} — files changed: {len(changed)}"
          f"  |  frontmatter unwraps: {total_fm}  |  body fixes: {total_body}")
    for p, f_n, b_n in changed[:verbose_limit]:
        print(f"   {os.path.relpath(p, ROOT)}   fm={f_n} body={b_n}")
    if len(changed) > verbose_limit:
        print(f"   ... and {len(changed) - verbose_limit} more")
    if apply_it and changed:
        print(f"backup -> {os.path.relpath(backup, ROOT)}")
    return 0


def selftest():
    """夹具：正例（该改）与反例（不该动）。"""
    fails = []
    # 正例 1：带双引号的作者链
    t = '---\ntitle: "x"\nauthor:\n  - "[[Zhang San]]"\n  - "[[Li Si]]"\ntags:\n  - "clippings"\n---\nbody [[keep]]\n'
    n, f, b = transform(t)
    if f != 2 or b != 0:
        fails.append(f"正例1 期望 fm=2 body=0，得 fm={f} body={b}")
    if '[[Zhang San]]' in split_frontmatter(n)[0]:
        fails.append("正例1 作者链未被解包")
    if '"Zhang San"' not in n:
        fails.append("正例1 未保留引号")
    # 正例 2：正文图注残留
    t2 = '---\nauthor:\n  - "[[A]]"\n---\n![[Uncaptioned image]](https://x/y.png)\n'
    n2, f2, b2 = transform(t2)
    if b2 != 1:
        fails.append(f"正例2 期望 body=1，得 {b2}")
    if "![[Uncaptioned image]]" in n2:
        fails.append("正例2 图注未被替换")
    if "![](https://x/y.png)" not in n2:
        fails.append("正例2 未产出 ![](url)")
    # 反例 1：author 之外的 [[ ]] 必须不动（sources 回链是正当链接）
    t3 = '---\nsources:\n  - "[[raw/clippings/x.md]]"\n---\nbody\n'
    _, f3, b3 = transform(t3)
    if f3 or b3:
        fails.append(f"反例1 误改了非 author 字段 (fm={f3},body={b3})")
    # 反例 2：wikilink 别名 \| 不得被误伤
    t4 = '---\nauthor:\n  - "[[A]]"\n---\nsee [[sources/X\\|别名]]\n'
    n4, _, _ = transform(t4)
    if "[[sources/X\\|别名]]" not in n4:
        fails.append("反例2 别名 wikilink 被误改")
    # 反例 3：normalization 不得吃掉闭合 --- 后的换行
    n5, _, _ = transform('---\nauthor:\n  - "[[A]]"\n---\nBODY\n')
    if not split_frontmatter(n5)[0] or split_frontmatter(n5)[1] != "BODY\n":
        fails.append("反例3 闭合 --- 后换行丢失")
    # 正例4（回归夹具）：无 frontmatter 的文件仍需修正文数学记号
    n6, f6, b6 = transform('all i ∈[[1, n]]. then\n')
    if b6 != 1 or "[[1, n]" not in n6 or "[[" == n6[:2]:
        fails.append(f"正例4 无frontmatter正文未修 (f={f6},b={b6},n6={n6!r})")
    if n6.startswith("---"):
        fails.append("正例4 给无frontmatter文件凭空加了 frontmatter")
    if fails:
        print("SELFTEST FAIL:")
        for f in fails:
            print("  -", f)
        return 1
    print("SELFTEST PASS (3 正例/反例组全部通过)")
    return 0


if __name__ == "__main__":
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__ or "用法: python tools/qc_unwrap_author_links.py [--apply] [--selftest]")
        sys.exit(0)
    if "--selftest" in sys.argv:
        sys.exit(selftest())
    sys.exit(run("--apply" in sys.argv))
